"use strict";(globalThis.webpackChunkbytesofpurpose_blog=globalThis.webpackChunkbytesofpurpose_blog||[]).push([[49205],{68795:e=>{e.exports=JSON.parse('{"tag":{"label":"claude-code","permalink":"/craft/tags/claude-code","allTagsPath":"/craft/tags","count":7,"items":[{"id":"generative-ai/claude-code-explainers/README","title":"Claude Code Explainers","description":"How parts of Claude Code work under the hood, with widgets to try it yourself. The technique pages link here for the background.","permalink":"/craft/generative-ai/claude-code-explainers"},{"id":"generative-ai/claude-code-explainers/how-the-prompt-cache-works","title":"How Claude Code\'s Prompt Cache Works","description":"What the prompt cache holds, what the 5-minute and 1-hour limits cost, and three calculators to try a day of pauses or a whole session.","permalink":"/craft/generative-ai/claude-code-explainers/how-the-prompt-cache-works"},{"id":"generative-ai/claude-code-techniques/skills-or-a-team-of-agents","title":"Skills, or a Team of Agents?","description":"The same work done by one agent loading skills and by a lead handing it to specialist subagents. The team cost 3.2 times as much, took 2.6 times as long, and the work came out about even.","permalink":"/craft/generative-ai/claude-code-techniques/skills-or-a-team-of-agents"},{"id":"generative-ai/claude-code-techniques/picking-the-prompt-cache-time-limit","title":"Tip: Ask Claude to Optimize Your Cache TTL","description":"The prompt cache can live 5 minutes or an hour. I measured my own pauses to see which one fits, and how to measure yours before you pick.","permalink":"/craft/generative-ai/claude-code-techniques/picking-the-prompt-cache-time-limit"},{"id":"generative-ai/claude-code-techniques/asking-your-sessions-to-coordinate","title":"Tip: Ask Your Claude Code Sessions to Coordinate","description":"Claude Code sessions on one machine can message each other. Ask one to tell another what changed, and stop copying answers between terminals.","permalink":"/craft/generative-ai/claude-code-techniques/asking-your-sessions-to-coordinate"},{"id":"generative-ai/claude-code-techniques/a-reminder-before-the-cache-runs-out","title":"Tip: Get a Mac Reminder Before Your 1-Hour Cache Runs Out","description":"A small helper that pops up about five minutes before a Claude Code session loses its 1-hour prompt cache, with a button that takes you to that session in iTerm, plus a status line clock showing when it runs out.","permalink":"/craft/generative-ai/claude-code-techniques/a-reminder-before-the-cache-runs-out"},{"id":"generative-ai/claude-code-techniques/keep-your-claude-code-session-logs","title":"Tip: Keep Your Claude Code Session Logs","description":"Claude Code deletes each session log after 30 days. What a log holds, why it is worth keeping, and one setting plus a backup to keep it.","permalink":"/craft/generative-ai/claude-code-techniques/keep-your-claude-code-session-logs"}],"unlisted":false}}')}}]);